-- Jeu de LecteurListeDeliberes (« Délibérés », PROC_LISTE_DELIBERES), lot 7 du plan « RIG v3 100 % fonctionnel » (plan-676a4b19).
-- Identifiants 1 701 xxx, roles 2026x171xx, sans code affaire (hors des listes d'instances des autres lots). Les tables des
-- audiences ont les MEMES definitions que dans PROC_RETAUD.sql (le premier jeu joue les cree, les suivants y ajoutent leurs
-- colonnes), aux types de RIG_DEV (RigDatabase\dbo\Tables\*.sql), plus les colonnes de la decision judiciaire et de l'instance que la
-- liste lit. La date de reference de RIG v2 est le dernier jour du mois precedent (frmListeDelibere.cs:61-63) : @ref, ci-dessous.
-- Ce qui est retenu ou ecarte, et pourquoi : PROC_LISTE_DELIBERES.attendu.
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ENROLEMENT') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ENROLEMENT datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_JUG') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_JUG int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_INSTN_INSTANCE_PRINCIPA') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_INSTN_INSTANCE_PRINCIPA int NULL;
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL, AUDNC_HEURE varchar(5) NULL);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_AUDIENCE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_AUDIENCE bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_CHAMBRE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_CHAMBRE varchar(5) NULL;
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_NUM_ORDRE smallint NOT NULL,
        APPAF_ID_ADNC int NOT NULL);
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_TYPE_CLASSEMENT') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_TYPE_CLASSEMENT varchar(5) NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_ETAT_PREPARATION') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_ETAT_PREPARATION varchar(1) NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_ETAT_RETOUR') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_ETAT_RETOUR varchar(1) NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_CODE_PLUMITIF') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_CODE_PLUMITIF varchar(16) NULL;
IF OBJECT_ID(N'v2.TYPE_CLASSEMENT') IS NULL
    CREATE TABLE v2.TYPE_CLASSEMENT (R_TYPECLASSE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_TYPECLASSE_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_TYPECLASSE_PRONONCE bit NOT NULL DEFAULT (0));
IF OBJECT_ID(N'v2.CODE_PLUMITIF') IS NULL
    CREATE TABLE v2.CODE_PLUMITIF (R_CODEPLUMIT_VALEUR varchar(16) NOT NULL PRIMARY KEY, R_CODEPLUMIT_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_CODEPLUMIT_UTILISABLE_SAISIE bit NOT NULL DEFAULT (1), R_CODEPLUMIT_CODE_EVE_PRO varchar(10) NULL, R_CODEPLUMIT_AVEC_AUDIENCE varchar(1) NULL,
        R_CODEPLUMIT_TYPE_CLASSEMENT varchar(5) NULL, R_CODEPLUMIT_DELIBERE bit NOT NULL DEFAULT (0), R_CODEPLUMIT_PRONONCE bit NOT NULL DEFAULT (0),
        R_CODEPLUMIT_CHAMBRE varchar(5) NULL, R_CODEPLUMIT_DELIBERE_REPOUSSE bit NOT NULL DEFAULT (0), R_CODEPLUMIT_RENVOI bit NOT NULL DEFAULT (0),
        R_CODEPLUMIT_COMPATIBLE_OP bit NOT NULL DEFAULT (0), R_CODEPLUMIT_COMPATIBLE_JC bit NOT NULL DEFAULT (0),
        R_CODEPLUMIT_COMPATIBLE_CX bit NOT NULL DEFAULT (0), R_CODEPLUMIT_COMPATIBLE_REF bit NOT NULL DEFAULT (0),
        R_CODEPLUMIT_COMPATIBLE_PC bit NOT NULL DEFAULT (0), R_CODEPLUMIT_COMPATIBLE_PRV bit NOT NULL DEFAULT (0));
IF OBJECT_ID(N'v2.JUGE') IS NULL
    CREATE TABLE v2.JUGE (JUG_ID_JUG int NOT NULL PRIMARY KEY, JUG_CIVILITE varchar(7) NOT NULL, JUG_NOM varchar(35) NOT NULL, JUG_PRENOM varchar(20) NULL);
IF COL_LENGTH('v2.JUGE', 'JUG_ACTIF') IS NULL ALTER TABLE v2.JUGE ADD JUG_ACTIF bit NOT NULL DEFAULT (1);
IF OBJECT_ID(N'v2.TYPE_DECISION') IS NULL
    CREATE TABLE v2.TYPE_DECISION (R_TYPEDECISI_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_TYPEDECISI_LIBELLE_ECRAN varchar(100) NOT NULL);
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_SYNONYME') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_SYNONYME varchar(16) NULL;
IF OBJECT_ID(N'v2.DECISION_JUDICIAIRE') IS NULL
    CREATE TABLE v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC int NOT NULL PRIMARY KEY, DCJDC_ID_INSTN int NOT NULL, DCJDC_NUM_ORDRE smallint NOT NULL);
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_DATE_PREVUE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_DATE_PREVUE datetime NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_DATE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_DATE datetime NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_TYPE_DECISION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_TYPE_DECISION varchar(10) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_LOCALISATION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_LOCALISATION varchar(100) NULL;

-- Codes : DL17 delibere (DELIBERE = 1, REPOUSSE = 0), DR17 delibere repousse (ecarte de la date de delibere, :141). Un type de
-- decision JGT17 (synonyme JGT). Le juge de 1701001.
EXEC sp_executesql N'
INSERT INTO v2.CODE_PLUMITIF (R_CODEPLUMIT_VALEUR, R_CODEPLUMIT_LIBELLE_ECRAN, R_CODEPLUMIT_DELIBERE, R_CODEPLUMIT_DELIBERE_REPOUSSE)
    VALUES (''DL17'', ''Délibéré du banc'', 1, 0), (''DR17'', ''Délibéré repoussé du banc'', 1, 1);
INSERT INTO v2.TYPE_CLASSEMENT (R_TYPECLASSE_VALEUR, R_TYPECLASSE_LIBELLE_ECRAN, R_TYPECLASSE_PRONONCE) VALUES (''TD17'', ''Délibérés du banc'', 0);
INSERT INTO v2.TYPE_DECISION (R_TYPEDECISI_VALEUR, R_TYPEDECISI_LIBELLE_ECRAN, R_TYPEDECISI_SYNONYME) VALUES (''JGT17'', ''Jugement du banc'', ''JGT'');
INSERT INTO v2.JUGE (JUG_ID_JUG, JUG_CIVILITE, JUG_NOM, JUG_PRENOM, JUG_ACTIF) VALUES (1701301, ''MME'', ''JUGEDELIB'', ''Anne'', 1);';

-- Les instances, enrolees 200 jours avant la reference, contentieux (07) sauf 1701005 (PC, 08) ; 1701007 enrolee apres la
-- reference. 1701009 est jointe a 1701001. Les audiences de delibere et leurs appels au code DL17, sauf 1701006 (DR17 seul).
-- 1701003 : une decision RENDUE 10 jours avant la reference, apres son delibere. 1701004 : une decision PREVUE 5 jours apres.
-- 1701108 est un CABINET (la liste ne filtre pas le mode) : a ref + 3, une audience tomberait dans la fenetre du retour
-- d'audience (PROC_RETAUD.attendu, [J-10 ; J]).
-- fix-ok: calcule -- @ref est entre J-31 et J-1, donc ref + 3 est entre J-28 et J+2 : du 4 au 13 du mois, une AUDIENCE a ref + 3
-- entrait dans la fenetre de PROC_RETAUD et y ajoutait une ligne ; en cabinet, elle n'y entre pas (mode audience par defaut).
EXEC sp_executesql N'
DECLARE @ref datetime = DATEADD(day, -DAY(@aujourdhui), @aujourdhui);
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_TYPE_INSTANCE, INSTN_DATE_ENROLEMENT, INSTN_ID_JUG,
    INSTN_ID_INSTN_INSTANCE_PRINCIPA) VALUES
    (1701001, ''2026J17101'', ''DELIB A'', ''07'', DATEADD(day, -200, @ref), 1701301, NULL),
    (1701002, ''2026J17102'', ''DELIB B'', ''07'', DATEADD(day, -200, @ref), NULL, NULL),
    (1701003, ''2026J17103'', ''DELIB C'', ''07'', DATEADD(day, -200, @ref), NULL, NULL),
    (1701004, ''2026J17104'', ''DELIB D'', ''07'', DATEADD(day, -200, @ref), NULL, NULL),
    (1701005, ''2026P17105'', ''DELIB PC'', ''08'', DATEADD(day, -200, @ref), NULL, NULL),
    (1701006, ''2026J17106'', ''DELIB REPOUSSE'', ''07'', DATEADD(day, -200, @ref), NULL, NULL),
    (1701007, ''2026J17107'', ''DELIB ENROLEE APRES'', ''07'', DATEADD(day, 1, @ref), NULL, NULL),
    (1701008, ''2026J17108'', ''DELIB APRES REF'', ''07'', DATEADD(day, -200, @ref), NULL, NULL),
    (1701009, ''2026J17109'', ''DELIB JOINTE'', ''07'', DATEADD(day, -200, @ref), NULL, 1701001);
INSERT INTO v2.AUDIENCE_CABINET (AUDNC_ID_ADNC, AUDNC_AUDIENCE, AUDNC_DATE, AUDNC_HEURE, AUDNC_CHAMBRE) VALUES
    (1701101, 1, DATEADD(day, -60, @ref), ''09:00'', NULL), (1701102, 1, DATEADD(day, -59, @ref), ''09:00'', NULL),
    (1701103, 1, DATEADD(day, -90, @ref), ''09:00'', NULL), (1701108, 0, DATEADD(day, 3, @ref), ''09:00'', NULL);
INSERT INTO v2.APPEL_AFFAIRE (APPAF_ID_APPAF, APPAF_ID_INSTN, APPAF_NUM_ORDRE, APPAF_ID_ADNC, APPAF_TYPE_CLASSEMENT, APPAF_ETAT_PREPARATION,
    APPAF_ETAT_RETOUR, APPAF_CODE_PLUMITIF) VALUES
    (1701201, 1701001, 1, 1701101, ''TD17'', ''0'', ''M'', ''DL17''), (1701202, 1701002, 1, 1701102, ''TD17'', ''0'', ''M'', ''DL17''),
    (1701203, 1701003, 1, 1701103, ''TD17'', ''0'', ''M'', ''DL17''), (1701204, 1701004, 1, 1701103, ''TD17'', ''0'', ''M'', ''DL17''),
    (1701205, 1701005, 1, 1701103, ''TD17'', ''0'', ''M'', ''DL17''), (1701206, 1701006, 1, 1701103, ''TD17'', ''0'', ''M'', ''DR17''),
    (1701207, 1701007, 1, 1701103, ''TD17'', ''0'', ''M'', ''DL17''), (1701208, 1701008, 1, 1701108, ''TD17'', ''0'', ''M'', ''DL17'');
INSERT INTO v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC, DCJDC_ID_INSTN, DCJDC_NUM_ORDRE, DCJDC_DATE_PREVUE, DCJDC_DATE, DCJDC_TYPE_DECISION,
    DCJDC_LOCALISATION) VALUES
    (1701401, 1701003, 1, NULL, DATEADD(day, -10, @ref), ''JGT17'', NULL),
    (1701402, 1701004, 1, DATEADD(day, 5, @ref), NULL, ''JGT17'', ''Salle 2'');', N'@aujourdhui datetime', @aujourdhui;
